{
  "tipo": "lista_de_recomendaciones_musicales",
  "titulo": "LA SENSACION DE CERTEZA — Selección de música (DJ)",
  "nota_de_enfoque": "Música pensada para montaje audiovisual: tensión controlada, sensación de inevitabilidad, y cortes rítmicos para evidencias/“veredictos”.",
  "curacion": [
    {
      "tramo": "SECUENCIA 1 (Plantear patrón inevitable)",
      "estilo": "Dark Ambient / Cinematic Drone",
      "tracks": [
        {
          "opcion": "Requiem for a Tower (tipo drone) — Tiersen/ambient similar (o cualquier drone sin melodía dominante)",
          "alternativas": [
            "The Shadow of the Sun (ambient/cinematic) — como referencia de atmósfera",
            "Any long-form drone en 50–70 BPM"
          ],
          "criterios": {
            "tempo_bpm": "50–70",
            "tono": "frío, estable, sin “gancho” emocional",
            "rango_frecuencias": "bajo + aire (evitar melodías que distraigan"
          }
        }
      ]
    },
    {
      "tramo": "Transición a herramientas (cuando aparece polarización/semántica)",
      "estilo": "Minimal Techno / Industrial Subtle",
      "tracks": [
        {
          "opcion": "Industrial minimal con percusión seca y bajos tight (sin voces)",
          "alternativas": [
            "Percusión glitch + kick constante (110–128 BPM)",
            "Texturas metálicas tipo idm/techno"
          ],
          "criterios": {
            "tempo_bpm": "118–128",
            "energia": "creciente, como “máquina” de certeza",
            "nota": "usar hits cortos sincronizados con cortes de texto"
          }
        }
      ]
    },
    {
      "tramo": "SECUENCIA 2 (Herramientas: polarización como inevitable, truco semántico)",
      "estilo": "Glitch / IDM tenso",
      "tracks": [
        {
          "opcion": "IDM con stutters y cortes (sin saturar la mezcla)",
          "alternativas": [
            "Electrónica glitch a 130–150 BPM",
            "Micropercusión + subgrave constante"
          ],
          "criterios": {
            "tempo_bpm": "130–150",
            "mood": "intervención quirúrgica (semántica = tijera)",
            "dinamica": "sube y corta en cada “mecanismo”"
          }
        }
      ]
    },
    {
      "tramo": "Momentos de “veredicto emocional” (cuando el montaje fuerza conclusión)",
      "estilo": "Cinematic Hybrid / Orchestral Suspense (sin sonar épico)",
      "tracks": [
        {
          "opcion": "String pads + percusión en staccato + bajos oscuros (sin triunfo)",
          "alternativas": [
            "Tensión orquestal moderna (latencia lenta, 70–95 BPM)",
            "Piano preparado muy mínimo (solo en puntos clave)"
          ],
          "criterios": {
            "tempo_bpm": "75–95",
            "nota": "mantenerlo “determinista”, como un fallo inapelable"
          }
        }
      ]
    },
    {
      "tramo": "Cierre (desarme del mecanismo: certeza revelada como construcción)",
      "estilo": "Ambient / Neo-classical tenue (o lo contrario: silencio)",
      "tracks": [
        {
          "opcion": "Ambient con progresión descendente o caída de resonancia",
          "alternativas": [
            "Reverb tail largo + sub que se apaga",
            "Un “mute” dramático en el último plano"
          ],
          "criterios": {
            "tempo_bpm": "60–80",
            "recurso": "reducir instrumentos gradualmente hasta casi silencio"
          }
        }
      ]
    }
  ],
  "paleta_sonora_sugerida": {
    "bpm_base": [
      "65 (drone)",
      "125 (tech/minimal)",
      "145 (glitch/IDM)",
      "85 (cinesuspense)"
    ],
    "instrumentacion": [
      "Drone / pads fríos",
      "Subgrave controlado",
      "Percusión seca y glitch (para “evidencia”)",
      "Cuerdas mínimas o piano sobrio (para veredicto)"
    ],
    "evitar": [
      "Canciones con letra (confunden el análisis)",
      "Melodías demasiado memorables (roban foco a titulares)",
      "Sonidos “optimistas” o épicos"
    ]
  },
  "suggested_playback_tips": [
    "Sincroniza los cortes con transientes (hits) para que el público “sienta” el argumento antes de entenderlo.",
    "Mantén el master entre -12 y -6 dB según el contenido de voz; reserva aire para la VOZ EN OFF.",
    "Usa filtros (low-pass) en transiciones para simular manipulación/edición semántica."
  ]
}
